use vstd::prelude::*;

verus! {

    // Specification function describing the reversal of a vector of integers
    spec fn vec_reverse(a: Seq<i32>) -> Seq<i32> {
        if a.len() == 0 {
            Seq::empty()
        } else {
            let n = a.len();
            seq![i in 0..n: a.index(n - 1 - i)]
        }
    }

    // Implementation of reversing a vector of i32, with full specification
    fn reverse(a: &Vec<i32>) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            // For all valid indices i, the element at i in result equals element at (n-1-i) in a
            forall(|i: usize| (i < a.len()) ==> result[i] == a[a.len() - 1 - i]),
    {
        let n = a.len();
        let mut result = Vec::with_capacity(n);

        // fill result with zeros initially to safely index
        // this is necessary because we cannot directly assign to arbitrary indices in an empty vector
        // alternatively push values and then swap, but this is a safe approach within Verus constraints
        let mut i = 0;
        while i < n
            invariant
                i <= n,
                result.len() == i,
                forall(|j: usize| (j < i) ==> result[j] == a[n - 1 - j]),
            decreases n - i,
        {
            result.push(a[n - 1 - i]);
            i += 1;
        }
        result
    }
}

